    }).join("");
    return ` + "`" + `<div class="story-section"><h3 style="color:${act.color};border-bottom:2px solid ${act.color};padding-bottom:4px;margin:12px 0 6px;">${act.label}</h3><div class="story-list">${cards}</div></div>` + "`" + `;
